{
        mongo_ops::insert_one(
            &self
                .db
                .collection::<SupplierFulfillmentOrder>(SUPPLIER_FULFILLMENT_ORDERS),
            order,
            executor,
        )
        .await?;
        mongo_ops::insert_many(
            &self
                .db
                .collection::<SupplierFulfillmentItem>(SUPPLIER_FULFILLMENT_ITEMS),
            items.to_vec(),
            executor,
        )
        .await?;
        mongo_ops::insert_one(
            &self.db.collection::<SupplierOrderAction>(SUPPLIER_ORDER_ACTIONS),
            action,
            executor,
        )
        .await?;
        Ok(())
    }

{
        mongo_ops::insert_one(
            &self.db.collection::<SupplierRefundFact>(SUPPLIER_REFUND_FACTS),
            fact,
            executor,
        )
        .await?;
        mongo_ops::insert_many(
            &self
                .db
                .collection::<SupplierRefundAllocation>(SUPPLIER_REFUND_ALLOCATIONS),
            allocations.to_vec(),
            executor,
        )
        .await?;
        Ok(())
    }

{
        if revision_ids.is_empty() {
            return Ok(HashMap::new());
        }
        let revision_id_strings = revision_ids.iter().map(ToString::to_string).collect::<Vec<_>>();
        let revisions = SupplierOfferingRevisionRepository::new(self.db, SUPPLIER_OFFERING_REVISIONS)
            .list_by_ids(&revision_id_strings, executor)
            .await?;
        let offering_ids = revisions
            .iter()
            .map(|revision| revision.supplier_offering_id.clone())
            .collect::<Vec<_>>();
        let offerings = SupplierOfferingRepository::new(self.db, SUPPLIER_OFFERINGS)
            .list_by_ids(&offering_ids, executor)
            .await?
            .into_iter()
            .map(|offering| (offering.base.id.clone(), offering))
            .collect::<HashMap<_, _>>();
        Ok(revisions
            .into_iter()
            .filter_map(|revision| {
                offerings
                    .get(revision.supplier_offering_id.as_ref())
                    .cloned()
                    .map(|offering| (revision.base.id, offering))
            })
            .collect())
    }

{
        let order_cost_gross = aggregate_single_total(
            &self.db.collection::<AmountTotalRow>(SUPPLIER_FULFILLMENT_ITEMS),
            financial_total_pipeline(order_id, "cost_snapshot_total_gross"),
            executor,
        )
        .await?;
        let refunded_total = aggregate_single_total(
            &self.db.collection::<AmountTotalRow>(SUPPLIER_REFUND_FACTS),
            financial_total_pipeline(order_id, "refund_amount"),
            executor,
        )
        .await?;
        Ok(RefundFinancialSnapshot {
            order_cost_gross,
            refunded_total,
        })
    }

{
        let facts = SupplierRefundFactRepository::new(self.db, SUPPLIER_REFUND_FACTS)
            .find_refund_facts_by_order_ids(std::slice::from_ref(order_id), executor)
            .await?;
        if facts.is_empty() {
            return Ok(Vec::new());
        }
        let fact_ids: Vec<SupplierRefundFactId> = facts
            .iter()
            .map(|fact| SupplierRefundFactId::new(fact.base.id.as_str()))
            .collect();
        let allocations = SupplierRefundAllocationRepository::new(self.db, SUPPLIER_REFUND_ALLOCATIONS)
            .find_allocations_by_fact_ids(&fact_ids, executor)
            .await?;
        Ok(group_refund_allocations(facts, allocations))
    }

{
    match executor.session() {
        Some(session) => {
            collection
                .aggregate(pipeline)
                .with_type::<T>()
                .session(&mut *session)
                .await?
                .stream(session)
                .try_collect::<Vec<_>>()
                .await
        }
        None => {
            collection
                .aggregate(pipeline)
                .with_type::<T>()
                .await?
                .try_collect::<Vec<_>>()
                .await
        }
    }
    .map_err(persistence_core::Error::from)
}

{
    vec![
        doc! {
            "$match": {
                "supplier_fulfillment_order_id": order_id.to_string(),
                "deleted_at": NOT_DELETED_TIMESTAMP_BSON,
            }
        },
        doc! {
            "$group": {
                "_id": mongodb::bson::Bson::Null,
                "total": { "$sum": format!("${amount_field}") },
            }
        },
        doc! { "$project": { "_id": 0 } },
    ]
}

{
    let mut by_fact: HashMap<String, Vec<SupplierRefundAllocation>> = HashMap::new();
    for allocation in allocations {
        by_fact
            .entry(allocation.supplier_refund_fact_id.to_string())
            .or_default()
            .push(allocation);
    }
    facts
        .into_iter()
        .map(|fact| {
            let mut allocations = by_fact.remove(fact.base.id.as_str()).unwrap_or_default();
            allocations.sort_by(|left, right| left.base.id.cmp(&right.base.id));
            SupplierRefundFactBundle { fact, allocations }
        })
        .collect()
}
